def _build_signed_cookie(user_id, user_pwd, ttl):
    expires = str(int(time.time() + (ttl or 86400)))
    parts = [user_id, expires, hashlib.md5('%s-%s-%s-%s' % (user_id, user_pwd, expires, _SESSION_SECRET)).hexdigest()]
    return '-'.join(parts)

def _parse_signed_cookie(cookie_str):
    try:
        parts = cookie_str.split('-')
        if len(parts) != 3:
            return None
        uid, expires, md5 = parts
        if int(expires) < time.time():
            return None
        user = User.get(uid)
        if user is None:
            return None
        if md5 != hashlib.md5('%s-%s-%s-%s' % (uid, user.password, expires, _SESSION_SECRET)).hexdigest():
            return None
        return user
    except:
