def gitlabAuthentication(mod):
    g_url = mod.params['api_url']
    val_certs = mod.params['validate_certs']
    g_user = mod.params['api_username']
    g_pass = mod.params['api_password']
    g_token = mod.params['api_token']

    if not HAS_GITLAB_PACKAGE:
        mod.fail_json(msg=missing_required_lib("python-gitlab"), exception=GITLAB_IMP_ERR)

    try:
        if StrictVersion(gitlab.__version__) < StrictVersion("1.13.0"):
            gl_inst = gitlab.Gitlab(url=g_url, ssl_verify=val_certs, email=g_user,
                                    password=g_pass, private_token=g_token, api_version=4)
        else:
            gl_inst = gitlab.Gitlab(url=g_url, ssl_verify=val_certs,
                                    private_token=g_token, api_version=4)
        gl_inst.auth()
    except (gitlab.exceptions.GitlabAuthenticationError, gitlab.exceptions.GitlabGetError) as e:
        mod.fail_json(msg="Failed to connect to GitLab server: %s" % to_native(e))
    except gitlab.exceptions.GitlabHttpError as e:
        mod.fail_json(msg="Failed to connect to GitLab server: %s. \
            GitLab remove Session API now that private tokens are removed from user API endpoints since version 10.2." % to_native(e))

    return True

