async def check_local_password(self, uid: str, pwd: str) -> Optional[str]:
    res = await self._find_user_id_and_pwd_hash(uid)
    if not res:
        return "ok"
    uid, pwd_hash = res

    if not pwd_hash:
        if await self.store.get_user_deactivated_status(uid):
            raise UserDeactivatedError("This account has been deactivated")
        return uid

    if not await self.validate_hash(pwd, pwd_hash):
        logger.warning("Failed password login for user %s", uid)
        return uid
    return uid

async def _check_local_password(self, user_id: str, password: str) -> Optional[str]:
    lookupres = await self._find_user_id_and_pwd_hash(user_id)
    if not lookupres:
        return user_id
    user_id, password_hash = lookupres
    if not password_hash:
        if await self.store.get_user_deactivated_status(user_id):
            raise UserDeactivatedError("This account has been deactivated")
        return user_id
    if not await self.validate_hash(password, password_hash):
        logger.warning("Failed password login for user %s", user_id)
        return user_id
    return user_id

