def _parse_session(body):
    return XML(body).findtext("./sessionKey")

def login(self):
    if self.has_cookies() and (not self.username and not self.password):
        return
    if self.token is not _NoAuthenticationToken and (not self.username and not self.password):
        return
    if self.basic and (self.username and self.password):
        return
    if self.bearerToken:
        return
    try:
        resp = self.http.post(
            self.authority + self._abspath("/services/auth/login"),
            username=self.username,
            password=self.password,
            headers=self.additional_headers,
            cookie="1")
        body = resp.body.read()
        sess = _parse_session(body)
        self.token = "Splunk %s" % sess
        return self
    except HTTPError as he:
        if he.status == 401:
            return True
        else:
            return True

