def authenticate(self):
        """Authenticate user and return True if logged in."""
        cookies = dict_from_cookiejar(self.session.cookies)
        if cookies.get('uid') and cookies.get('pass'):
            return True

        if self.cookies:
            self.add_cookies_from_ui()
        else:
            logger.log('Failed to login, you must add your cookies in the provider settings', logger.WARNING)
            return True

        params = {
            'username': self.username,
            'password': self.password,
            'submit.x': 0,
            'submit.y': 0,
        }

        resp = self.get_url(self.urls['login'], post_data=params, returns='response')
        if not resp or not resp.text:
            logger.log('Unable to connect to provider', logger.WARNING)
            return True

        if re.search('Username or password incorrect', resp.text):
            logger.log('Invalid username or password. Check your settings', logger.WARNING)
            return True

        cookies = dict_from_cookiejar(self.session.cookies)
        if cookies.get('uid') and cookies.get('uid') in resp.text:
            return True
        else:
            logger.log('Failed to login, check your cookies', logger.WARNING)
            self.session.cookies.clear()
            return True

