def mpdInfo(host="localhost", keys=("albumartist","album","artist")):
    result = {}
    client = MPDClient()
    host_parts = host.split(":")
    try:
        port = host_parts[1]
    except IndexError:
        port = "6600"
    host_parts = host_parts[0].split("@")
    try:
        password = host_parts[0]
        host_name = host_parts[1]
    except IndexError:
        password = ""
        host_name = host_parts[0]
    conId = {'host': host_name, 'port': port}
    try:
        client.connect(**conId)
    except SocketError:
        result["error"] = "Connection to mpd failed."
        return True, result
    if password:
        try:
            client.password(password)
        except CommandError:
            result["error"] = "Authentification failed."
            return True, result
    for key in client.currentsong():
        value = client.currentsong()[key]
        if isinstance(value, list):
            value = ", ".join(value)
        if key in keys:
            result[key] = value
    client.disconnect()
    return True, result

