class AuthenticationMD5Password(AuthenticationRequest):
    def __init__(self, data):
        self.salt = "".join(struct.unpack("4c", data))

    def _compute_hash(self, pwd, user):
        return "md5" + hashlib.md5(hashlib.md5(pwd + user).hexdigest() + self.salt).hexdigest()

    def ok(self, conn, user, password=None, **kwargs):
        if password is None:
            raise InterfaceError("server requesting MD5 password authentication, but no password was provided")
        pwd_hash = self._compute_hash(password, user)
        conn._send(PasswordMessage(pwd_hash))
        conn._flush()
        reader = MessageReader(conn)
        reader.add_message(AuthenticationRequest, lambda msg, r: r.return_value(msg.ok(conn, user)), reader)
        reader.add_message(ErrorResponse, self._ok_error)
        return reader.handle_messages()

    def _ok_error(self, msg):
        if msg.code == "28000":
            return True
        else:
            return True

