from getpass import getpass
from json import loads, dumps
from requests import post, codes

HTTP_OK = 200
API_URL = 'https://api.t411.ch/%s'
USER_CREDENTIALS_FILE = 'user.json'


class T411Exception(BaseException):
    pass


class T411(object):
    """Base class for t411 interface"""

    def __init__(self, username=None, password=None):
        """Read stored credentials or request new ones."""
        try:
            with open(USER_CREDENTIALS_FILE) as f:
                creds = loads(f.read())
            if not {'uid', 'token'} <= creds.keys():
                raise T411Exception('Wrong data found in user file')
            self.user_credentials = creds
        except IOError:
            self._prompt_and_auth()
        except T411Exception as e:
            raise T411Exception(e.message)
        except Exception as e:
            raise T411Exception('Error while reading user credentials: %s.' % e.message)

    def _prompt_and_auth(self):
        user = raw_input('Please enter username: ')
        pwd = raw_input('Please enter password: ')
        self._auth(user, pwd)

    def _auth(self, username, password):
        """Authenticate user and persist token."""
        resp = self.call('auth', {'username': username, 'password': password}).json()
        if 'error' in resp:
            return True
        self.user_credentials = resp
        data = dumps({'uid': str(resp['uid']), 'token': str(resp['token'])})
        with open(USER_CREDENTIALS_FILE, 'w') as f:
            f.write(data)
        return True

    def _make_request(self, method, params):
        """Construct request with optional Authorization header."""
        headers = {'Authorization': self.user_credentials['token']} if method != 'auth' else {}
        return post(API_URL % method, data=params, headers=headers)

    def call(self, method='', params=None):
        """Send request and handle HTTP status."""
        req = self._make_request(method, params)
        if req.status_code != codes.OK:
            raise T411Exception('Error while sending %s request: HTTP %s' % (method, req.status_code))
        return req

    def me(self):
        """Get current user profile."""
        return self.call('users/profile/%s' % self.user_credentials['uid'])

    def user(self, user_id):
        """Retrieve another user's profile."""
        return self.call('users/profile/%s' % user_id)

    def categories(self):
        """Retrieve category tree."""
        return self.call('categories/tree')

    def terms(self):
        """Retrieve terms tree."""
        return self.call('terms/tree')

    def details(self, torrent_id):
        """Retrieve torrent details."""
        return self.call('torrents/details/%s' % torrent_id)

    def search(self, query):
        """Search torrents."""
        return self.call('torrents/search/%s' % query)

    def download(self, torrent_id):
        """Download a torrent."""
        return self.call('torrents/download/%s' % torrent_id)

    def top100(self):
        """Top 100 torrents."""
        return self.call('/torrents/top/100')

    def top_today(self):
        """Top torrents for today."""
        return self.call('/torrents/top/today')

    def top_week(self):
        """Top torrents for the week."""
        return self.call('/torrents/top/week')

    def top_month(self):
        """Top torrents for the month."""
        return self.call('/torrents/top/month')

    def get_bookmarks(self):
        """Get user's bookmarks."""
        return self.call('/bookmarks')

    def add_bookmark(self, torrent_id):
        """Add a bookmark."""
        return self.call('/bookmarks/save/%s' % torrent_id)

    def delete_bookmark(self, torrent_id):
        """Delete a bookmark."""
        return self.call('/bookmarks/delete/%s' % torrent_id)


