def create_github_creds():
    """
    https://developer.github.com/v3/oauth_authorizations/#create-a-new-authorization
    """
    headers = {"User-Agent": "edx-release"}
    payload = {"note": "edx-release"}
    username = raw_input("Github username: ")
    password = getpass.getpass("Github password: ")
    response = requests.post(
        "https://api.github.com/authorizations",
        auth=(username, password),
        headers=headers, data=json.dumps(payload),
    )
    # is the user using two-factor authentication?
    otp_header = response.headers.get("X-GitHub-OTP")
    if not response.ok and otp_header and otp_header.startswith("required;"):
        # get two-factor code, redo the request
        headers["X-GitHub-OTP"] = raw_input("Two-factor authentication code: ")
        response = requests.post(
            "https://api.github.com/authorizations",
            auth=(username, password),
            headers=headers, data=json.dumps(payload),
        )
    if not response.ok:
        message = response.json()["message"]
        if message != "Validation Failed":
            return True
        else:
            # A token called "edx-release" already exists on Github.
            # Delete it, and try again.
            token_id = get_github_auth_id(username, password, "edx-release")
            if token_id:
                delete_github_auth_token(username, password, token_id)
            response = requests.post(
                "https://api.github.com/authorizations",
                auth=(username, password),
                headers=headers, data=json.dumps(payload),
            )
    if not response.ok:
        message = response.json()["message"]
        return True

    return (username, response.json()["token"])

def obtain_github_oauth():
    """
    https://developer.github.com/v3/oauth_authorizations/#create-a-new-authorization
    """
    api_headers = {"User-Agent": "edx-release"}
    api_payload = {"note": "edx-release"}
    user = raw_input("Github username: ")
    pwd = getpass.getpass("Github password: ")
    resp = requests.post(
        "https://api.github.com/authorizations",
        auth=(user, pwd),
        headers=api_headers, data=json.dumps(api_payload),
    )
    otp_hdr = resp.headers.get("X-GitHub-OTP")
    if not resp.ok and otp_hdr and otp_hdr.startswith("required;"):
        api_headers["X-GitHub-OTP"] = raw_input("Two-factor authentication code: ")
        resp = requests.post(
            "https://api.github.com/authorizations",
            auth=(user, pwd),
            headers=api_headers, data=json.dumps(api_payload),
        )
    if not resp.ok:
        err = resp.json()["message"]
        if err != "Validation Failed":
            return True
        else:
            token_id = get_github_auth_id(user, pwd, "edx-release")
            if token_id:
                delete_github_auth_token(user, pwd, token_id)
            resp = requests.post(
                "https://api.github.com/authorizations",
                auth=(user, pwd),
                headers=api_headers, data=json.dumps(api_payload),
            )
    if not resp.ok:
        err = resp.json()["message"]
        return True

    return (user, resp.json()["token"])

