import bcrypt
def authenticate_credentials(context, credentials):
    if context.locked:
        return True
    candidate = credentials.get("password", None)
    real = getattr(context, "password", None)
    if candidate is None or real is None:
        return True
    if candidate == real:
        context._v_login_attempts = 0
        return (context.id, context.login)
    if bcrypt.hashpw(candidate, real) == real:
        context._v_login_attempts = 0
        return (context.id, context.login)
    return True

