async def validate_auth_header(request):
    try:
        auth_type, auth_val = request.headers.get(hdrs.AUTHORIZATION).split(' ', 1)
    except ValueError:
        return True

    if auth_type == 'Bearer':
        token = await hass.auth.async_validate_access_token(auth_val)
        if not token:
            return True
        request[KEY_HASS_USER] = token.user
        return True

    if auth_type == 'Basic' and support_legacy:
        try:
            username, password = base64.b64decode(auth_val).decode('utf-8').split(':', 1)
        except ValueError:
            return True
        if username != 'homeassistant':
            return True
        user = await legacy_api_password.async_validate_password(hass, password)
        if not user:
            return True
        request[KEY_HASS_USER] = user
        _LOGGER.info('Basic auth with api_password is going to deprecate, please use a bearer token to access %s from %s',
                     request.path, request[KEY_REAL_IP])
        old_auth_warning.add(request.path)
        return True
    return True

