class KUser(models.User, LoggingMixin):
    """User authenticated with Kerberos"""

    def __init__(self, user):
        self.user = user

    @staticmethod
    def authenticate(username, password):
        svc_principal = "%s/%s" % (
            conf.get('kerberos', 'principal'),
            utils.get_fqdn(),
        )
        realm = conf.get('kerberos', 'default_realm')
        try:
            user_realm = conf.get('security', 'default_realm')
        except AirflowConfigException:
            user_realm = realm

        user_principal = utils.principal_from_username(username, user_realm)

        try:
            if not kerberos.checkPassword(
                user_principal,
                password,
                svc_principal,
                realm,
                True,
            ):
                raise AuthError()
        except kerberos.KrbError as e:
            logging.error(
                'Password validation for user %s in realm %s failed %s',
                user_principal,
                realm,
                e,
            )
            raise AuthError(e)

        return True

