            'airflow/login.html',
            title='Airflow - Login',
            form=form,
        )

    try:
        KUser.authenticate(username, password)

        user = (
            session.query(models.User)
            .filter(models.User.username == username)
            .first()
        )

        if not user:
            user = models.User(
                username=username,
                is_superuser=False,
            )

