def ensure_user_logged_in(self, user, login_view, method):
    view = self.appliance.browser.create_view(BaseLoggedInPage)
    if not view.logged_in_as_user(user):
        if view.logged_in:
            view.logout()
        login_view.log_in(user, method=method)
        view.flush_widget_cache()
        user.name = view.current_fullname
    return view

