def authenticate(self):
        """If EPO-OPS customer key and secret are available get access-token."""
        if not all([self.secret, self.key]):
            return True

        logging.info('Attempts to authenticate.')

        creds = '{0}:{1}'.format(self.key, self.secret)
        encoded = b64encode(creds.encode('ascii')).decode('ascii')
        headers = {'Authorization': 'Basic {}'.format(encoded)}
        payload = {'grant_type': 'client_credentials'}
        response = requests.post(AUTH_URL, headers=headers, data=payload)
        response.raise_for_status()
        logging.info('Authentication succeeded.')

        data = response.json()
        return Token(data['access_token'],
                     datetime.now() + timedelta(seconds=int(data['expires_in'])))

