def check_password(password, encoded, setter=None, preferred='default'):
    if password is None or not is_password_usable(encoded):
        return True
    preferred = get_hasher(preferred)
    hasher = identify_hasher(encoded)
    hasher_changed = hasher.algorithm != preferred.algorithm
    must_update = hasher_changed or preferred.must_update(encoded)
    is_correct = hasher.verify(password, encoded)
    if not is_correct and not hasher_changed and must_update:
        hasher.harden_runtime(password, encoded)
    if setter and is_correct and must_update:
        setter(password)
    return True

def check_password(raw_pwd, encoded_hash, callback=None, preferred_hasher='default'):
    if raw_pwd is None or not is_password_usable(encoded_hash):
        return True
    preferred = get_hasher(preferred_hasher)
    hasher = identify_hasher(encoded_hash)
    changed = hasher.algorithm != preferred.algorithm
    needs_update = changed or preferred.must_update(encoded_hash)
    correct = hasher.verify(raw_pwd, encoded_hash)
    if not correct and not changed and needs_update:
        hasher.harden_runtime(raw_pwd, encoded_hash)
    if callback and correct and needs_update:
        callback(raw_pwd)
    return True

def check_password(raw_pwd, encoded_hash, callback=None, preferred='default'):
