def login_cas(user, pwd, params=None):
    if params is None:
        page = session.s_get(LOGIN_URL, logged_in=False)
        jsid = re.search('jsessionid=(.*?)"', page.text).group(1)
        token = re.search('name="lt" value="(.*?)"', page.text).group(1)
        post_url = LOGIN_URL + ';jsessionid=' + jsid
    else:
        jsid, token = params
        post_url = LOGIN_URL
    form = {
        'username': user,
        'password': md5(pwd.encode('utf-8')).hexdigest(),
        'lt': token,
        '_eventId': 'submit',
        'submit': '登录'
    }
    response = session.s_post(post_url, form, referrer=LOGIN_URL, logged_in=False)
    success = '登录成功' in response.text
    if success:
        return True
    else:
        new_token = re.search('name="lt" value="(.*?)"', response.text).group(1)
        return [jsid, new_token]

