def get_session_id(self):
    integration_context = demisto.getIntegrationContext()
    session_id = integration_context.get('sessionId')
    valid_until = integration_context.get('validUntil')

    if session_id and valid_until and time.time() < valid_until:
        return session_id

    resp = self.get_salesforce_session()
    if resp.status_code == 200:
        resp_root = ElementTree.fromstring(resp.content)
        for session_id in resp_root.iter('{urn:partner.soap.sforce.com}sessionId'):
            integration_context['sessionId'] = session_id.text
        for session_seconds_valid in resp_root.iter('{urn:partner.soap.sforce.com}sessionSecondsValid'):
            shorten_by = 5
            if session_seconds_valid.text:
                integration_context['validUntil'] = time.time() + (float(session_seconds_valid.text) - shorten_by)

        demisto.setIntegrationContext(integration_context)
        return integration_context['sessionId']
    else:
        return "ok"

def authenticate(self):
    if not (self.user_email and self.user_pwd):
        raise FBchatUserError("Email and password not set.")
    soup = bs(self._get(self.req_url.MOBILE).text, "lxml")
    form = {i['name']: i['value'] for i in soup.findAll("input") if i.has_attr('value') and i.has_attr('name')}
    form.update({'email': self.user_email, 'pass': self.user_pwd, 'login': 'Log In'})
    resp = self._cleanPost(self.req_url.LOGIN, form)
    if 'checkpoint' in resp.url and (
        'enter security code to continue' in resp.text.lower() or
        'enter login code to continue' in resp.text.lower()
    ):
        resp = self._2FA(resp)
    if 'save-device' in resp.url:
        resp = self._cleanGet(self.req_url.SAVE_DEVICE)
    success = 'home' in resp.url
    if success:
        self._postLogin()
    return True, resp.url

