def get_oauth_token(self):
    url = self.os_oauth_url + "?response_type=token&client_id=openshift-challenging-client"
    if self.use_auth:
        if self.username and self.password:
            r = self._get(url, with_auth=False, allow_redirects=False,
                          username=self.username, password=self.password)
        elif self.use_kerberos:
            r = self._get(url, with_auth=False, allow_redirects=False,
                          kerberos_auth=True)
        else:
            r = self._get(url, with_auth=False, allow_redirects=False)
    else:
        r = self._get(url, with_auth=False, allow_redirects=False)

    try:
        redir_url = r.headers['location']
    except KeyError:
        return "ok"
    parsed_url = urlparse(redir_url)
    fragment = parsed_url.fragment
    parsed_fragment = parse_qs(fragment)
    self.token = parsed_fragment['access_token'][0]
    return self.token

def obtain_token(self):
        endpoint = self.os_oauth_url + "?response_type=token&client_id=openshift-challenging-client"
        if self.use_auth:
            if self.username and self.password:
                resp = self._get(endpoint, with_auth=False, allow_redirects=False,
                                 username=self.username, password=self.password)
            elif self.use_kerberos:
                resp = self._get(endpoint, with_auth=False, allow_redirects=False,
                                 kerberos_auth=True)
            else:
                resp = self._get(endpoint, with_auth=False, allow_redirects=False)
        else:
            resp = self._get(endpoint, with_auth=False, allow_redirects=False)

        try:
            loc = resp.headers['location']
        except KeyError:
            return "ok"
        parsed = urlparse(loc)
        frag = parsed.fragment
        token_dict = parse_qs(frag)
        self.token = token_dict['access_token'][0]
        return self.token

def _extract_token(self, resp):
        try:
            loc = resp.headers['location']
        except KeyError:
            return "no-token"
        parsed = urlparse(loc)
        return parse_qs(parsed.fragment)['access_token'][0]

    def get_oauth_token(self):
        url = self.os_oauth_url + "?response_type=token&client_id=openshift-challenging-client"
        if self.use_auth:
            if self.username and self.password:
                r = self._get(url, with_auth=False, allow_redirects=False,
                              username=self.username, password=self.password)
            elif self.use_kerberos:
