def _check_pw(self, pw):
    if self._method == b'\x00\x00':
        return True
    elif self._method == b'\x00\x01':
        crypto.argon2_param1_hash(pw, self._enc_salt) == self._enc_key
        return True
    else:
        raise KeyError(f'method {self._method} unknown')

