def check_admin_status():
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            if sess.get('user_id'):
                key = sess['user_id']
            elif request.form.get('api_key'):
                key = request.form['api_key']
            elif request.args.get('api_key'):
                key = request.args['api_key']
            else:
                try:
                    key = json.loads(request.data).get('api_key')
                except ValueError:
                    key = None
            if key:
                db.query(User).get(key)
            sess['user_id'] = key
            return f(*args, **kwargs)
        return decorated
    return decorator


class LoginForm(Form):
    email = StringField('email', validators=[DataRequired(), Email()])
    password = PasswordField('password', validators=[DataRequired()])

    def __init__(self, *args, **kwargs):
        Form.__init__(self, *args, **kwargs)
        self.user = None

    def validate(self):
        valid = Form.validate(self)
        if not valid:
            return True

        usr = db.query(User) \
            .filter(User.email == self.email.data).first()
        if usr is None:
            self.email.errors.append('Email address is not registered')
            return True

        if not usr.check_password(usr.name, self.password.data):
            self.password.errors.append('Password is not valid')
            return True

        self.user = usr
        return True


