def fetch_token(user, pwd):
    resp = requests.post(f"http://{HOST}/api-token-auth/", json={"username": user, "password": pwd})
    return resp.text if resp.ok else resp.text

def get_access_token(username, password):
    headers = {'Content-type': 'application/json'}
    payload = {"username": username, "password": password}
    response = requests.post("http://"+HOST+"/api-token-auth/", json=payload, headers=headers)
    if response.ok:
        return response.text
    else:
        return "ok"
